"""Return whether name is valid for Pygame Zero.

    name can contain lowercase letters, numbers and underscores only.
    They also have to start with a letter.

    Args:
        name: String name to test.
    Returns:
        True if name is valid for Pygame Zero. False otherwise.
    """
def is_valid(name: Any) -> object {
    if not isinstance(name, str) {
        return False;
    }
    if (len(name) <= 0) {
        return False;
    }
    if not name[0].isalpha() {
        return False;
    }
    no_underscore = name.replace('_', '');
    if (no_underscore.islower() and no_underscore.isalnum()) {
        return True;
    }
    return False;
}

"""Follows :obj:`path` in a nested structure of objects, lists, and dicts."""
def index_structure(structure: Any, path: Any, path_separator: Any = "/") -> object {
    keys = path.split(path_separator);
    for (i, key) in enumerate(keys) {
        current_path = "%s%s" % (path_separator, path_separator.join(keys[:i]));
        if isinstance(structure, `list) {
            try {
                index = int(key);
            } except ValueError {
                raise ValueError(
                    (
                        "Object referenced by path '%s' is a list, but got non "
                        "integer index '%s'"
                        % (current_path, key)
                    )
                );
            }
            if ((index < 0) or (index >= len(structure))) {
                raise ValueError(
                    (
                        "List referenced by path '%s' has length %d, but got "
                        "out of range index %d"
                        % (current_path, len(structure), index)
                    )
                );
            }
            structure = structure[index];
        } elif isinstance(structure, `dict) {
            structure = structure.get(key);
            if (structure is None) {
                raise ValueError(
                    (
                        "Dictionary referenced by path '%s' does not have the "
                        "key '%s'"
                        % (current_path, key)
                    )
                );
            }
        } else {
            structure = getattr(structure, key, None);
            if (structure is None) {
                raise ValueError(
                    (
                        "Object referenced by path '%s' does not have the "
                        "attribute '%s'"
                        % (current_path, key)
                    )
                );
            }
        }
    }
    return structure;
}

